MultiLanguageSpellData['de'][223844] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Dieses handliche Gerät wurde von Sterndeutern eingesetzt, um immense Mengen von Sternenlicht auf einen kleinen Punkt zu konzentrieren. Es kam größtenteils bei Feierlichkeiten und Sternverehrungsritualen zum Einsatz... oder wenn der Sterndeuter etwas von einem hohen Regalbrett herunterholen musste."}
MultiLanguageSpellData['de'][223845] = {name = "Ast des Arcan'dor", additional_info = "100 Meter Reichweite\nSofort\n[q]Ihr habt 1 Verdorrte betört.\n\n Bringt sie nach Shal'Aran oder klickt mit der rechten Maustaste auf diesen Effekt, um sie freizugeben.\n\n Das Verlassen von Suramar bricht diesen Effekt ab."}
MultiLanguageSpellData['de'][223846] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Die regierenden Prinzen und Prinzessinnen Suramars entschieden sich, ihre Kronjuwelen lediglich zu formalen Anlässen anzulegen. Sie blieben zu allen anderen Zeiten unter Verschluss, da sie als unmodisch betrachtet wurden."}
MultiLanguageSpellData['de'][223847] = {name = "Betörter Verdorrter fortgeschritten", additional_info = nil}
MultiLanguageSpellData['de'][223848] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Die Rabenwehr wurde von einer kleinen Armee an Dienern instand gehalten. Einer dieser Diener namens Kalyndras war für die Waffenkammer und das Munitionslager der Rabenwehr verantwortlich. Wie die meisten der Diener auf der Rabenwehr fiel auch er im Krieg der Ahnen den Dämonen zum Opfer."}
MultiLanguageSpellData['de'][223849] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Dieser unglaublich mächtige Zauberfokus der Hochgeborenen wurde im Verlauf einer rücksichtslosen archäologischen Expedition so stark beschädigt, dass er in viele Splitter zersprang. Heute sind nur noch diese Splitter übrig."}
MultiLanguageSpellData['de'][223850] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Dieser Schlüssel öffnet keine Tür. Er ist vielmehr eine zeremonielle Geste, der die Einladung zur Akademie symbolisiert - eine Art, \"Unsere Türen stehen Euch offen!\" zu sagen."}
MultiLanguageSpellData['de'][223851] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Der von Bergarbeitern und Schmieden gleichsam verehrte Rethu Eisenhorn war einer der ersten Taurensiedler auf den Verheerten Inseln. Seine Nachkommen führen seine Tradition der Eisenverarbeitung in der Eisenhornenklave fort, die sich in der Nähe des Hochberggipfels befindet."}
MultiLanguageSpellData['de'][223852] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Die Drogbar waren schon immer Meister der Juwelierskunst. Insbesondere Stammesschamanen trugen oft schwere Halsketten mit Besätzen aus drei Steinen. Diese Halsketten wurden vom Meister an den Schüler weitergereicht."}
MultiLanguageSpellData['de'][223853] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Eche'ro war der geliebte Begleiter, das Reittier und der Kampfgefährte von Huln Hochberg, dem legendären Helden des Kriegs der Ahnen."}
MultiLanguageSpellData['de'][223854] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Das Auge eines machtvollen Dämons, im kalten und steinigen Untergrund Sturmheims konserviert. Schriften aus der Zeit des Kriegs der Ahnen besagen, dass Undravius ein Teufelslordkommandant war, der danach trachtete, alles Leben von Azeroth zu tilgen."}
MultiLanguageSpellData['de'][223855] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Unter der Anleitung unkooperativer Ingenieure der Mo'arg waren Dämonenjäger in der Lage, mehrere dieser Portale nach Mardum zu erschaffen. Die Idee hat sich leider nicht durchgesetzt, da sie für gewöhnlich mehr Dämonen hinaus- als hineinlassen."}
MultiLanguageSpellData['de'][223856] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Viele tollkühne Abenteurer haben die Aktivierung eines dieser Geräte, ohne ihre Funktion zu kennen, mit dem Leben bezahlt. Es ist häufig unklar, ob sie lediglich einen einzelnen Wichtel oder eine ganze Legion Grubenlords beschwören."}
MultiLanguageSpellData['de'][223857] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]Es bleibt unklar, warum irgendeine Kreatur - ob nun dämonisch oder azerothisch - sich willentlich unbeliebt bei Mannoroth machen sollte, indem sie sein Blut in einem Einmachglas aufbewahrt."}
MultiLanguageSpellData['de'][223858] = {name = "Archäologieprojekt", additional_info = "Sofort\n[q]In ihrer Eile nahmen die Draenei nur wenige Artefakte mit sich, als sie Argus verließen. Dieses Buch ist eines der wenigen Relikte, die die Zeit bis heute überstanden haben."}
