MultiLanguageSpellData['de'][223892] = {name = "Verbündeten verwandeln", additional_info = "40 Meter Reichweite\n{Kanalisiert (Wirken in} {10 sek.) 10 sek. Abklingzeit}\n[q]Lässt nach 10 Sek. 'Dunkles Flüstern' in die Gedanken eines Verbündeten sickern.\n\n Der Einsatz dieser Fähigkeit wird Euch für 15 Sek. als Verbündeten der Legion zu erkennen geben.\n\n Entfernt einen Stapel von 'Schwacher Geist'."}
MultiLanguageSpellData['de'][223894] = {name = "Hysterie", additional_info = "50 Meter ReichweiteWirken in 2 sek. 1 min Abklingzeit\n[q]Ruft bei einer Gruppe von Zielen eine Hysterie hervor, die sie für 10 Sek. gegen ihre Verbündeten kämpfen lässt.\n\n Der Einsatz dieser Fähigkeit wird Euch für 15 Sek. als Verbündeten der Legion zu erkennen geben.\n\n Die Fähigkeit trifft keine Ziele, die kürzlich bereits hysterisch waren."}
