MultiLanguageSpellData['de'][225124] = {name = "Sande der Zeit", additional_info = "1 sek. Abklingzeit\n[q]Absorbiert bis zu 53269 Schaden eines Angriffs, der Euch töten würde. Wenn dieser Effekt auftritt, werdet Ihr sofort um 3987 Gesundheit geheilt und erleidet danach im Verlauf von 10 Sek. den gesamten verhinderten Schaden. Dies kann nur einmal alle 6 Min. geschehen."}
MultiLanguageSpellData['de'][225125] = {name = "Accelerando", additional_info = "Ca. 12 Procs pro Minute\n[q]Eure Schadenszauber haben eine Chance, Euch 12 Sek. lang 35 Tempo zu gewähren. Dieser Effekt ist bis zu 5-mal stapelbar. Die einzelnen Stapel erneuern nicht die Effektdauer."}
MultiLanguageSpellData['de'][225126] = {name = "Köstlicher Kuchen!", additional_info = "3 Meter Reichweite\nSofort 2 min Abklingzeit\n[q]Erschafft für 20 Sek. ein magisches Festmahl. Bis zu 5 Verbündete, die am Festmahl teilnehmen, absorbieren 12 Sek. lang 4001 Schaden."}
MultiLanguageSpellData['de'][225127] = {name = "Arkaner Hieb", additional_info = "1 sek. Abklingzeit\nCa. 5 Procs pro Minute\n[q]Eure Nahkampfangriffe haben eine Chance, alle Gegner vor Euch zu zerfetzen und ihnen 324 Arkanschaden zuzufügen."}
MultiLanguageSpellData['de'][225128] = {name = "Gelassenheit des Nachtbrunnens", additional_info = "Ca. 3 Procs pro Minute\n[q]Eure Heilzauber haben eine Chance, dem Ziel 'Gelassenheit des Nachtbrunnens' zu gewähren, die im Verlauf von 12 Sek. 1342 Gesundheit regeneriert. Das Heilen eines Ziels, das von 'Gelassenheit des Nachtbrunnens' betroffen ist, kann eine Detonation auslösen, die Verbündete in der Nähe um 224 Gesundheit heilt."}
MultiLanguageSpellData['de'][225129] = {name = "Triumvirat", additional_info = "Ca. 0.7 Procs pro Minute\n[q]Eure Nahkampf- und Distanzangriffe haben eine Chance, Euch für 20 Sek. eine Feuer-, Frost- oder Arkanverzauberung zu gewähren."}
MultiLanguageSpellData['de'][225130] = {name = "Vampiraura", additional_info = "Sofort 1 min Abklingzeit\n[q]Gewinnt für 12 Sek. 228 Lebensraub."}
MultiLanguageSpellData['de'][225131] = {name = "Aasschwarm", additional_info = "100 Meter Reichweite\nCa. 1.5 Procs pro Minute\n[q]Eure Distanzangriffe und Zauber haben eine Chance, einen Aasschwarm zu entfesseln, der alle Gegner in einer Linie vor Euch infiziert und ihnen im Verlauf von 8 Sek. ( 471 * 4) Schattenschaden zufügt."}
MultiLanguageSpellData['de'][225132] = {name = "Kolossales Schmettern", additional_info = "Sofort 1 min Abklingzeit\n[q]Entfesselt ein kolossales Schmettern, das immer kritisch trifft und 2671 körperlichen Schaden verursacht, der gleichmäßig unter allen Gegnern in der Nähe aufgeteilt wird. Wenn Ihr weniger als 3 Ziele trefft, wird die Abklingzeit der Fähigkeit um 15 Sek. verringert."}
MultiLanguageSpellData['de'][225133] = {name = "Sphäre der Zerstörung", additional_info = "10 - 40 Meter Reichweite\nSofort 1 min Abklingzeit\n[q]Entsendet eine Sphäre der Zerstörung zur Position Eures Ziels in mindestens 10 Metern Entfernung, die nach 4 Sek. allen Gegnern innerhalb von 20 Metern 3071 Schattenschaden zufügt. Ziele, die sich näher an der Explosion befinden, erleiden mehr Schaden."}
MultiLanguageSpellData['de'][225134] = {name = "Solarkollaps", additional_info = "Ca. 2 Procs pro Minute\n[q]Eure Distanzangriffe und Zauber haben eine Chance, an der Position Eures Ziels einen Solarkollaps hervorzurufen, der nach 3 Sek. Gegnern in der Nähe 1413 Feuerschaden zufügt.\n(3s Abklingzeit)"}
MultiLanguageSpellData['de'][225135] = {name = "Rekursive Schläge", additional_info = "Ca. 1 Procs pro Minute\n[q]Eure Angriffe haben eine Chance, dass Euch 15 Sek. lang der Effekt 'Rekursive Schläge' gewährt wird, wodurch Eure automatischen Angriffe zusätzlich 161 Schaden verursachen und die Intensität von 'Rekursive Schläge' erhöht wird."}
MultiLanguageSpellData['de'][225136] = {name = "Konstellationen", additional_info = "1 sek. Abklingzeit\nCa. 2 Procs pro Minute\n[q]Eure Heilzauber haben eine Chance, Eure Meisterschaft, Euer Tempo oder Euren kritischen Trefferwert für 8 Sek. um 207 zu erhöhen."}
MultiLanguageSpellData['de'][225137] = {name = "Sternentor", additional_info = "Ca. 3 Procs pro Minute\n[q]Eure Schadenszauber haben eine Chance, einen Meteor aus dem Wirbelnden Nether herabzurufen, der Eurem Ziel und allen Gegnern in der Nähe 496 Zauberfeuerschaden zufügt."}
MultiLanguageSpellData['de'][225138] = {name = "Zeitverschiebung", additional_info = "Ca. 1.2 Procs pro Minute\n[q]Eure Heilzauber haben eine Chance, Euren nächsten Einsatz eines direkten Heilzaubers 79 Mana wiederherstellen zu lassen, anstatt Mana zu kosten."}
MultiLanguageSpellData['de'][225139] = {name = "Voraussicht", additional_info = "Ca. 3 Procs pro Minute\n[q]Eure Angriffe haben eine Chance, die verbleibende Abklingzeit einer Eurer mächtigen Fähigkeiten um 3 Sek. zu verringern. Gilt nicht für Eure Spezialisierung."}
