MultiLanguageSpellData['de'][235656] = {name = "Anpassung: Bebende Schritte", additional_info = "Sofort\n[q]Die Beine des Zaubernden lassen den Boden erbeben. Jedes Mal, wenn er sich bewegt, werden nahe Gegner von den Schockwellen seiner Schritte zurückgestoßen."}
