MultiLanguageSpellData['de'][236011] = {name = "Schmerzensschreie", additional_info = "200 Meter Reichweite\nSofort\n[q]Markiert einen Spielercharakter und erzeugt in einem kegelförmigen Bereich in Richtung des Ziels gequälte Magie, die 23470 Schattenschaden verursacht. Dieser Schaden wird um 300% erhöht, wenn das Ziel sich bereits im Effektbereich von ' Schmerzensschreie ' aufhält.\n Sich im Bereich der gequälten Seelen aufzuhalten, verursacht alle 1 Sek. 5848 Schattenschaden und bringt das Ziel zum Schweigen."}
MultiLanguageSpellData['de'][236012] = {name = "Malornes Schnelligkeit", additional_info = "[q]Auf Schlachtfeldern und in Arenen wird Eure Bewegungsgeschwindigkeit in Reisegestalt um 20% erhöht. Außerdem bewegt Ihr Euch in Reisegestalt immer mit 100% Bewegungsgeschwindigkeit."}
