MultiLanguageSpellData['de'][236019] = {name = "Stärke der Wildnis", additional_info = "[q]Ihr werdet noch geschickter im Umgang mit Eurer nicht verwandelten Gestalt und Eurer Bärengestalt.\n\nNicht verwandelte Gestalt\n Wenn Ihr 'Nachwachsen' auf einen Verbündeten wirkt, ist die kritische Trefferchance der Initialheilung um 30% erhöht. Außerdem wird die Zauberzeit von 'Nachwachsen' für 6 Sek. um 50% verringert.\n\nBärengestalt\n Während Ihr Euch in Bärengestalt befindet, ist Eure maximale Gesundheit um 15% erhöht und Ihr erzeugt 5 Wut, wenn Ihr angegriffen werdet.\n\n Zusätzlich erlernt Ihr:\n\n Stärke der Wildnis\nZermalmt das Ziel und fügt ihm 8% seiner maximalen Gesundheit als körperlichen Schaden zu."}
MultiLanguageSpellData['de'][236020] = {name = "Wilde Wunde", additional_info = "[q]Ein Angriff mit 'Wilder Biss' mit 5 Combopunkten verringert die maximale Gesundheit des Ziels 30 Sek. lang um bis zu 3%. Dieser Effekt ist bis zu 2-mal stapelbar. 'Wilde Wunde' kann immer nur auf einem Ziel gleichzeitig aktiv sein."}
MultiLanguageSpellData['de'][236021] = {name = "Wilde Wunde", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Ein Angriff mit 'Wilder Biss' mit 5 Combopunkten verringert die maximale Gesundheit des Ziels 30 Sek. lang um bis zu 3%. Dieser Effekt ist bis zu 2-mal stapelbar. 'Wilde Wunde' kann immer nur auf einem Ziel gleichzeitig aktiv sein."}
