MultiLanguageSpellData['de'][239412] = {name = "[q5]Celumbra, Dichotomie der Nacht", additional_info = "Wirken in 2 sek.\nReagenzien:\nSchattenstoffballen , Sternengewebeballen , Nethersplitteressenz , Blut von Sargeras (65), Machtgetränktes Seidengewebe (125), Scharfer Waldgeistdorn , Runenfaden aus Katgut\n[q]Stellt Celumbra, Dichotomie der Nacht, her.\nBerufsausbilder:\nSchneiderei der Verheerten Inseln (100)\nKosten:\n250\n\n[q5]Celumbra, Dichotomie der Nacht\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)Schulter Stoff\n3 Rüstung\n+4 Intelligenz\n+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Tempowertung um + 4.\n\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n\nHaltbarkeit 120 / 120\nKlassen: Priester , Magier , Hexenmeister\n[q2]Anlegen: Wenn sich ein Gegner innerhalb von 12 Metern um Euch befindet, werdet Ihr in Schatten gehüllt, die Euren erlittenen Schaden um 5% verringern und Eure Bewegungsgeschwindigkeit um 10% erhöhen. Wenn sich keine Gegner innerhalb von 12 Metern um Euch befinden, heilt Euch Celumbras Sternenlicht alle 1 Sek. um 1% Eurer maximalen Gesundheit.\n40\n[q]\"Schatten und Sterne, Dunkelheit und Licht, Verzweiflung und Hoffnung.\""}
MultiLanguageSpellData['de'][239413] = {name = "[q5]Ewiges Refugium der Schildwache", additional_info = "Wirken in 2 sek.\nReagenzien:\nIrrwischberührter Urbalg , Nethersplitteressenz , Blut von Sargeras (65), Steinbalgleder (250)\n[q]Stellt das ewige Refugium der Schildwache her.\nBerufsausbilder:\nLederverarbeitung der Verheerten Inseln (100)\nKosten:\n250\n\n[q5]Ewiges Refugium der Schildwache\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)Füße Leder\n5 Rüstung\n+4 [Beweglichkeit oder Intelligenz]+6 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n\nHaltbarkeit 95 / 95\nKlassen: Schurke , Mönch , Druide , Dämonenjäger\n[q2]Anlegen: Jedes Mal, wenn Ihr einen Gegner tötet, wird Eure Bewegungsgeschwindigkeit 1 Min. lang um 5% erhöht. Bis zu 5-mal stapelbar. Bei 5 Stapeln verwandelt Ihr Euch außerhalb des Kampfes in einen Irrwisch, was Eure Bewegungsgeschwindigkeit zusätzlich erhöht und Euch die Fähigkeit zu fliegen gewährt.\n40\n[q]\"Ihr Geist erfüllt das Leder dieser Stiefel und wird so an diese Welt gebunden.\""}
MultiLanguageSpellData['de'][239414] = {name = "[q5]Träger der Weisheit", additional_info = "Wirken in 2 sek.\nReagenzien:\nErstklassige Wächterschuppen , Nethersplitteressenz , Blut von Sargeras (65), Sturmschuppe (250)\n[q]Stellt die Träger der Weisheit her.\nBerufsausbilder:\nLederverarbeitung der Verheerten Inseln (100)\nKosten:\n250\n\n[q5]Träger der Weisheit\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)Hände Kette\n7 Rüstung\n+4 [Beweglichkeit oder Intelligenz]+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 3.\n[q2]Erhöht Eure Meisterschaftswertung um + 4.\n\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n\nHaltbarkeit 70 / 70\nKlassen: Jäger , Schamane , Rufer\n[q2]Anlegen: Jedes Mal, wenn Ihr einen Gegner tötet, wird Eure Bewegungsgeschwindigkeit 1 Min. lang um 5% erhöht. Bis zu 5-mal stapelbar. Bei 5 Stapeln verwandelt Ihr Euch außerhalb des Kampfes in eine Geistereule, was Eure Bewegungsgeschwindigkeit zusätzlich erhöht und Euch die Fähigkeit zu fliegen gewährt.\n40\n[q]\"Selbst nach dem Tod wachen die Geister der Eulen noch über ihre Meister, solange ein sicher geführter Handschuh sie trägt.\""}
MultiLanguageSpellData['de'][239415] = {name = "[q5]Rethus unerschöpflicher Mut", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nHammer der vergessenen Helden , Nethersplitteressenz , Blut von Sargeras (65), Dämonenstahlbarren (125)\n[q]Stellt Rethus unerschöpflichen Mut her.\nBerufsausbilder:\nSchmiedekunst der Verheerten Inseln (100)\nKosten:\n250\n\n[q5]Rethus unerschöpflicher Mut\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Legion - legendär (1)Taille Platte\n10 Rüstung\n+4 [Stärke oder Intelligenz]+6 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 4.\n[q2]Erhöht Eure Meisterschaftswertung um + 3.\n\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n[q0]Prismatischer Sockel\n\nHaltbarkeit 70 / 70\nKlassen: Krieger , Paladin , Todesritter\n[q2]Anlegen: Wenn sich ein Gegner innerhalb von 8 Metern von Euch befindet, werdet Ihr alle 3 Sek. um 2% Eurer maximalen Gesundheit geheilt. Wenn sich keine Gegner innerhalb von 8 Metern von Euch befinden, wird Eure Bewegungsgeschwindigkeit um 15% erhöht.\n40\n[q]\"Sein Mut wirkte ansteckend.\""}
