MultiLanguageSpellData['de'][239645] = {name = "Teufelsschätze", additional_info = "Sofort\n[q]Wenn Ihr den Bau des Magierturms abschließt, erhaltet Ihr Zugriff auf:\n\nArtefaktherausforderungen\n Der Rat der Sechs gewährt Zugriff auf eine Reihe einzigartiger Herausforderungen, bei denen würdige Helden ihre Kraft und ihr Geschick auf die Probe stellen können.\n\nVerhüllte Wyrmzungenschatztruhen\n Die Macht des Magierturms pulsiert über die Verheerte Küste hinweg und offenbart die lukrativen verhüllten Wyrmzungenschatztruhen.\n\nPortalnetzwerk\n Die Kirin Tor gewähren Zugang zu Portalen, mit denen Ihr Euch schnell über die Verheerten Inseln bewegen könnt."}
MultiLanguageSpellData['de'][239646] = {name = "Umarmung des Lichts", additional_info = "Sofort\n[q]Schützt vor Schaden."}
MultiLanguageSpellData['de'][239647] = {name = "Epischer Jäger", additional_info = "Sofort\n[q]Wenn Ihr den Bau des Netherdisruptors abschließt, erhaltet Ihr Zugriff auf:\n\nWeltbosse\n Die Energie des Netherdisruptors zieht die mächtigsten Gegner zur Verheerten Küste.\n\nInstabile Netherportale\n Die Aktivierung des Netherdisruptors lässt überall an der Verheerten Küste instabile Netherportale entstehen. Aktiviert sie, um gefährliche Gegner zu beschwören.\n\nBelobigungen des Rüstungsmachers\n Die geschicktesten Handwerker werden für ihre Anstrengungen Belobigungen erhalten, mit denen sie legendäre Gegenstände herstellen können."}
MultiLanguageSpellData['de'][239648] = {name = "Streitkräfte des Ordens", additional_info = "Sofort\n[q]Nachdem der Bau der Kommandozentrale abgeschlossen ist, erhaltet Ihr Zugriff auf:\n\nKathedralenweltquests\n Jetzt, da die Kommandozentrale erbaut ist, könnt Ihr Euch darauf konzentrieren, die Kathedrale der Ewigen Nacht anzugreifen.\n\nVerstärkungstruppen der Legionsrichter\n Kommandanten der Legionsrichter können überall auf den Verheerten Inseln zusätzliche Verstärkung anfordern.\n\nEliteeinsatz\n Sendet würdige Champions auf eine herausfordernde, aber lukrative Mission tief ins Inland der Verheerten Küste."}
