MultiLanguageSpellData['de'][247614] = {name = "Vantusrune: Antorus, der Brennende Thron", additional_info = "Wirken in 2 sek.\nReagenzien:\nFahle Pigmente (10), Rosenrote Pigmente (30)\n[q]Erschafft eine Vantusrune: Antorus, der Brennende Thron.\nBeute von:\nAntorus, der Brennende Thron\n\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\n45"}
MultiLanguageSpellData['de'][247615] = {name = "Vantusrune: Antorus, der Brennende Thron", additional_info = "Wirken in 2 sek.\nReagenzien:\nFahle Pigmente (8), Rosenrote Pigmente (30)\n[q]Verringert die erforderlichen Materialien zur Herstellung einer Vantusrune: Antorus, der Brennende Thron.\nBeute von:\nAntorus, der Brennende Thron\n\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Antorus, dem Brennenden Thron, ein, was Eure Vielseitigkeit um 3380 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\n45"}
