MultiLanguageSpellData['de'][247692] = {name = "Andenkenkontinuum", additional_info = "[q]Erhöht Eure Chance, eine Andenkenschachtel aus Sanden der Zeit zu erbeuten. Andenkenschachteln enthalten mächtige Gegenstände, die den Schwierigkeitsgrad von Chronoportalherausforderungen stark verringern.\n\nBonus: Erhöht die Bewegungs- und Reitgeschwindigkeit um 10%."}
