MultiLanguageSpellData['de'][247694] = {name = "[q4]Astraler Alchemistenstein", additional_info = "Wirken in 3 sek.\nReagenzien:\nAstralwinde (75), Infernaler Alchemistenstein , Ursargerit (5)\n[q]Stellt einen astralen Alchemistenstein her.\nQuest:\nAnsteigende Alchemie\nZone:\nKrokuun\n\n[q4]Astraler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n45\nBenötigtAlchemie der Verheerten Inseln\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\""}
MultiLanguageSpellData['de'][247695] = {name = "[q4]Astraler Alchemistenstein", additional_info = "Wirken in 3 sek.\nReagenzien:\nAstralwinde (60), Infernaler Alchemistenstein , Ursargerit (4)\n[q]Stellt einen astralen Alchemistenstein effizienter her.\nVerkäufer:\nToraan der Verehrte\nZone:\nArgus\nKosten:\n2000\n\n[q4]Astraler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n45\nBenötigtAlchemie der Verheerten Inseln\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\""}
MultiLanguageSpellData['de'][247696] = {name = "[q4]Astraler Alchemistenstein", additional_info = "Wirken in 3 sek.\nReagenzien:\nAstralwinde (50), Infernaler Alchemistenstein , Ursargerit (3)\n[q]Stellt einen astralen Alchemistenstein noch effizienter her.\nVerkäufer:\nToraan der Verehrte\nZone:\nArgus\nKosten:\n3000\n\n[q4]Astraler Alchemistenstein\nWird beim Anlegen gebunden\nEinzigartig anlegbarSchmuck\n[q2]+ 7 Vielseitigkeit\n[q2]Anlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass sich Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 19 erhöht. Es wird stets Euer höchster Wert gewählt.\n[q2]Anlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n45\nBenötigtAlchemie der Verheerten Inseln\n(1)\n[q]\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\""}
