MultiLanguageSpellData['de'][253087] = {name = "Antorischer Schattenhund", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren antorischen Schattenhund oder gibt ihn wieder frei.\n[q]\"Sargeras' Hund war möglicherweise einst ein Teufelspirscher, doch im Laufe der Jahre formte der Dunkle Titan seinen Begleiter neu und ließ ihn deutlich mächtiger werden. Als er schließlich zufrieden war mit seinem Werk, erschuf er noch mehr Hunde und erfüllte sie mit Schatten und Flamme.\"\nErfolg:\nRuhm des Schlachtzüglers von Argus\nKategorie:\nDungeons & Schlachtzüge"}
MultiLanguageSpellData['de'][253088] = {name = "Antorischer Aschenhund", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren antorischen Aschenhund oder gibt ihn wieder frei.\n[q]\"Sargeras' Hund war möglicherweise einst ein Teufelspirscher, doch im Laufe der Jahre formte der Dunkle Titan seinen Begleiter neu und ließ ihn deutlich mächtiger werden. Als er schließlich zufrieden war mit seinem Werk, erschuf er noch mehr Hunde und erfüllte sie mit Schatten und Flamme.\"\nBeute von:\nShatug\nZone:\nAntorus, der Brennende Thron"}
