MultiLanguageSpellData['de'][253106] = {name = "Farbenprächtiger Manarochen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen farbenprächtigen Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Einige Tierarten auf Argus, wie beispielsweise der Manarochen, haben überlebt und sich an das Leben auf der zerschmetterten Welt angepasst.\"\nBeute von:\nTeufelsgeflecktes Ei"}
MultiLanguageSpellData['de'][253107] = {name = "Glimmernder Manarochen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen flackernden Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Einige Tierarten auf Argus, wie beispielsweise der Manarochen, haben überlebt und sich an das Leben auf der zerschmetterten Welt angepasst.\"\nBeute von:\nGiftschwanzhimmelsflosse\nZone:\nEredath"}
MultiLanguageSpellData['de'][253108] = {name = "Teufelsschimmermanarochen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen Teufelsschimmermanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Die Armee des Lichts konnte nicht alle heimischen Spezies auf Argus retten. Unzählige gingen im Chaos verloren.\"\nBeute von:\nTeufelsgeflecktes Ei"}
MultiLanguageSpellData['de'][253109] = {name = "Schillernder Manarochen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört einen schillernden Manarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n[q]\"Einige Tierarten auf Argus, wie beispielsweise der Manarochen, haben überlebt und sich an das Leben auf der zerschmetterten Welt angepasst.\"\nBeute von:\nTeufelsgeflecktes Ei"}
MultiLanguageSpellData['de'][253110] = {name = "Monelitgehärtete Hufplatten", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nMoneliterz (25), Langlebiger Fluxus (2)\n[q]Stellt monelitgehärtete Hufplatten her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (50)\nLehrer:\nSchmiedemeister Zak'aal\nZone:\nZuldazar\nKosten:\n2\n\n[q2]Benutzen: Beschlägt Euer Reittier mit Hufplatten, die Eure Geschwindigkeit beim Reiten in Kul Tiras oder Zandalar für 2 Stunden um 20% erhöhen.\n\n Die Dauer ist für Schmiede vervierfacht."}
MultiLanguageSpellData['de'][253111] = {name = "Umarmung des Lichts", additional_info = "Rang 1/ 3[q0]Artefakt Boni\nCa. 8 Procs pro Minute\n[q]Wenn Ihr Schaden erleidet, besteht eine Chance, dass Ihr 'Umarmung des Lichts' erhaltet. Der Effekt stellt im Verlauf von 6 Sek. 45500 Gesundheit wieder her. 'Umarmung des Lichts' ist bis zu 5-mal stapelbar.\n(1s Abklingzeit)"}
MultiLanguageSpellData['de'][253112] = {name = "Monelitgehärtete Steigbügel", additional_info = "Wirken in 2 sek.\nTools: Schmiedehammer\nReagenzien:\nMoneliterz (25), Langlebiger Fluxus (2)\n[q]Stellt monelitgehärtete Steigbügel her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (50)\nLehrer:\nSchmiedemeister Zak'aal\nZone:\nZuldazar\nKosten:\n2\n\n[q2]Benutzen: Versieht Euer Reittier mit Steigbügeln, die Euch für 2 Stunden Interaktionen beim Reiten in Kul Tiras oder Zandalar ermöglichen.\n\n Die Dauer ist für Schmiede vervierfacht."}
MultiLanguageSpellData['de'][253113] = {name = "[q2]Monelitgehärteter Schild", additional_info = "Wirken in 2.5 sek.\nTools: Schmiedehammer\nReagenzien:\nMoneliterz (18), Langlebiger Fluxus (3)\nOptionale Reagenzien:\n[] (#48)\n[q]Stellt einen monelitgehärteten Schild her.\nBeruf:\nSchmiedekunst von Battle for Azeroth (15)\nLehrer:\nSchmiedemeister Zak'aal\nZone:\nZuldazar\nKosten:\n50\n\nAllianz\n[q2]Monelitgehärteter Schild\nWird beim Anlegen gebunden\nSchildhand Schild\n59 Rüstung\n+3 Stärke\n+9 Intelligenz\n+4 Ausdauer\nHaltbarkeit 85 / 85\n45\nHorde\n[q2]Monelitgehärteter Schild\nWird beim Anlegen gebunden\nSchildhand Schild\n59 Rüstung\n+3 Stärke\n+9 Intelligenz\n+4 Ausdauer\nHaltbarkeit 85 / 85\n45"}
