MultiLanguageSpellData['de'][254411] = {name = "Purge", additional_info = "{4% von Grundmana} {30 Meter Reichweite}\nSofort\n[q]Purges the enemy target, removing 1 beneficial Magic effect.[Successfully purging a target grants a stack of Maelstrom Weapon.]"}
MultiLanguageSpellData['de'][254412] = {name = "Hex", additional_info = "30 Meter Reichweite\n{Wirken in} {1.7 sek. 35 sek. Abklingzeit}\n[q]Transforms the enemy into a frog for 1 Min.. While hexed, the victim is incapacitated, and cannot attack or cast spells. Damage may cancel the effect. Limit 1. Only works on Humanoids and Beasts."}
MultiLanguageSpellData['de'][254413] = {name = "Healing Tide Totem", additional_info = "1.12% von Grundmana\nSofort 3 min Abklingzeit\n[q]Summons a totem at your feet for 10 Sek., which pulses every 2 sec, healing all party or raid members within 40 yards for (350% der Zaubermacht)."}
MultiLanguageSpellData['de'][254414] = {name = "Ghost Wolf", additional_info = "Sofort\n[q]Turn into a Ghost Wolf, increasing movement speed by 30% and preventing movement speed from being reduced below 100%."}
MultiLanguageSpellData['de'][254415] = {name = "Earthbind Totem", additional_info = "35 Meter Reichweite\n{Sofort} {30 sek. Abklingzeit}\n[q]Summons an Earth Totem with (2 * Gesamtgesundheit / 100) health at the target location for 20 Sek. that slows the movement speed of enemies within 10 yards."}
MultiLanguageSpellData['de'][254416] = {name = "Grounding Totem", additional_info = "1.18% von Grundmana\n{Sofort} {30 sek. Abklingzeit}\n[q]Summons an Air Totem with 5 health at the feet of the caster that will redirect all harmful spells cast on a nearby party or raid member to itself. Will not redirect area of effect spells. Lasts 3 Sek.."}
MultiLanguageSpellData['de'][254417] = {name = "Earth Shield", additional_info = "{3% von Grundmana} {40 Meter Reichweite}\n{Sofort} {6 sek. Abklingzeit}\n[q]Protects the target with an earthen shield, reducing all damage the target receives by 15% and causes the target to be healed for (112.5% der Zaubermacht) when they take an attack equal to 4% of their total health. 4 Charges.\n\n Earth Shield can only be placed on one target at a time.\n(1s Abklingzeit)"}
MultiLanguageSpellData['de'][254418] = {name = "Healing Surge", additional_info = "{4% von Grundmana} {40 Meter Reichweite}\nWirken in 1.5 sek.\n[q]A quick surge of healing energy that restores 10 of a friendly target's health."}
MultiLanguageSpellData['de'][254419] = {name = "Riptide", additional_info = "{1.6% von Grundmana} {40 Meter Reichweite}\n{Sofort} {6 sek. Abklingzeit}\n[q]Restorative waters wash over a friendly target, healing them for 5 and an additional 10 over 15 Sek.."}
MultiLanguageSpellData['de'][254420] = {name = "Purify Spirit", additional_info = "{2.6% von Grundmana} {40 Meter Reichweite}\n{Sofort} {8 sek. Abklingzeit}\n[q]Removes all Curse and Magic effects from a friendly target."}
MultiLanguageSpellData['de'][254421] = {name = "Healing Wave", additional_info = "{1.8% von Grundmana} {40 Meter Reichweite}\nWirken in 2.5 sek.\n[q]An efficient wave of healing energy that restores 20 of a friendly target’s health."}
MultiLanguageSpellData['de'][254422] = {name = "Healing Stream Totem", additional_info = "2.2% von Grundmana\n{Sofort} {30 sek. Abklingzeit}\n[q]Summons a totem at your feet for 15 Sek. that heals [ Rauschende Ströme : two injured party or raid members / an injured party or raid member] within 40 yards for (67.68% der Zaubermacht) every 2 sec."}
MultiLanguageSpellData['de'][254423] = {name = "Chain Heal", additional_info = "{5% von Grundmana} {40 Meter Reichweite}\nWirken in 2.5 sek.\n[q]Heals the friendly target for 5, then jumps to heal the most injured nearby party or raid members. Healing is reduced by 30 % after each jump. Heals 4 total targets."}
MultiLanguageSpellData['de'][254424] = {name = "Lava Burst", additional_info = "{1.2% von Grundmana} {40 Meter Reichweite}\n{Wirken in} {2 sek. 8 sek. Abklingzeit}\n[q]Hurls molten lava at the target, dealing 2 Fire damage.\n\nElementar, Verstärkung\nGenerates 12 Maelstrom."}
MultiLanguageSpellData['de'][254425] = {name = "Earth Shield", additional_info = "300 Meter Reichweite\nSofort\n[q]Schützt das Ziel mit einem Erdschild, der dessen gesamten erlittenen Schaden um 10% verringert. Wenn es durch einen Angriff Schaden in Höhe von 4% seiner gesamten Gesundheit erleidet, wird es um (112.5% der Zaubermacht) Gesundheit geheilt. 4 Aufladungen.\n\n 'Erdschild' kann immer nur auf ein Ziel gleichzeitig gewirkt werden."}
