MultiLanguageSpellData['de'][256301] = {name = "[q4]Lana'thels blutiger Federkiel", additional_info = "Wirken in 3.5 sek.\nReagenzien:\nVergoldete Feder , Uralte Blutpigmente , Geronnenes Miasma (50), Blutrote Tinte (30), Grünliche Tinte (15), Expulsom (10)\n[q]Stellt Lana'thels blutigen Federkiel her.\nQuest:\nDie Federkielprüfung\nZone:\nZuldazar\n\n[q4]Lana'thels blutiger Federkiel\nWird beim Aufheben gebunden\nEinzigartig\n[q2]Erlaubt die Herstellung von Blutverträgen.\n[q2]Benutzen: Entzieht den Toten in Eurer Nähe das Blut und stellt dabei Eure Gesundheit wieder her.\n50\nBenötigtInschriftenkunde von Kul Tiras\n(150)\n[q]\"Es ist unklar, ob Lana'thel den Federkiel selbst erschaffen oder nur als Inspiration für das Design gedient hat.\""}
MultiLanguageSpellData['de'][256302] = {name = "Vantusrune: Uldir", additional_info = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\n[q]Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Uldir ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen."}
MultiLanguageSpellData['de'][256303] = {name = "Vantusrune: Uldir", additional_info = "Wirken in 2 sek.\nReagenzien:\nLeichtes Pergament , Blutrote Tinte (20), Grünliche Tinte (10)\n[q]Erschafft eine Vantusrune: Uldir.\nBeute von:\nUldir\n\nSchatz:\nMUTTERs Truhe\nZone:\nUldir\n\n[q2]Benutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus Uldir ein, was Eure Vielseitigkeit um 2078 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\n Ihr könnt nur eine Vantusrune pro Woche nutzen.\n45"}
