MultiLanguageSpellData['de'][256815] = {name = "Mal von Aggramar", additional_info = "Ca. 1.4 Procs pro Minute\n[q]Erlittener Schaden hat eine Chance, Eure Vielseitigkeit 14 Sek. lang um 181 zu erhöhen.\n\nAggramars Seelenstärke\n Wenn Euch das Pantheon Macht verleiht, wird Eure maximale Gesundheit 15 Sek. lang um 1654 erhöht und Ihr werdet um 17291 Gesundheit geheilt."}
