MultiLanguageSpellData['de'][256833] = {name = "Golganneths donnernde Wut", additional_info = "Sofort\n[q]Eure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 172 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\n Wenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 96 ] Naturschaden zufügt. Hält 15 Sek. lang an."}
MultiLanguageSpellData['de'][256834] = {name = "Eonars tiefgrüne Umarmung", additional_info = "Sofort\n[q]Eure Heileffekte haben eine Chance, in der Nähe eine Smaragdblüte wachsen zu lassen, die einen zufälligen verletzten Verbündeten alle 2 Sek. um 275 Gesundheit heilt. Hält 12 Sek. lang an.\n\nEonars tiefgrüne Umarmung\n Wenn Euch das Pantheon Macht verleiht, gewähren Eure nächsten 4 Einsätze von direkter Heilung dem Ziel einen Schild, der 30 Sek. lang 414 Schaden verhindert."}
MultiLanguageSpellData['de'][256835] = {name = "Khaz'goroths Schmiedeschlag", additional_info = "Sofort\n[q]Eure Schaden verursachenden Angriffe haben eine Chance, Eure Waffe durch die Flammen von Khaz'goroths Schmiede 12 Sek. lang erglühen zu lassen, wodurch Eure automatischen Angriffe zusätzlich ( 1 * Haupthandwaffen-Min-Grundgeschwindigkeit * 141 ) Feuerschaden verursachen.\n\nKhaz'goroths Schmiedeschlag\n Wenn Euch das Pantheon Macht verleiht, wird Euer kritischer Trefferwert, Euer Tempo, Eure Meisterschaft oder Eure Vielseitigkeit 15 Sek. lang um 176 erhöht. Khaz'goroth erhöht immer Euren höchsten Wert."}
MultiLanguageSpellData['de'][256836] = {name = "Norgannons Befehl", additional_info = "Sofort\n[q]Eure Schaden verursachenden Zauber haben eine Chance, Eure Intelligenz 12 Sek. lang um 146 zu erhöhen.\n\nNorgannons Befehl\n Wenn Euch das Pantheon Macht verleiht, erhaltet Ihr 15 Sek. lang 6 Aufladungen von 'Norgannons Befehl'. Eure Schaden verursachenden Zauber verbrauchen eine Aufladung, um dem Ziel zusätzlich 221 Schaden durch eine zufällige Magieart zuzufügen."}
