MultiLanguageSpellData['de'][257616] = {name = "Säbelhieb", additional_info = "{25 Energie} {Nahkampfreichweite}\nSofort\nBenötigt Nahkampfwaffe\n[q]Schlitzt einen Gegner brutal auf und verursacht 4 körperlichen Schaden.\n\nGewährt für jeden Treffer 4 Combopunkte."}
MultiLanguageSpellData['de'][257617] = {name = "Emporstoßen", additional_info = "Sofort\n[q]Verschwindet in den Sand und bricht unter einem Spielercharakter wieder hervor. Dieser Ausbruch verursacht 12229 Naturschaden und schleudert alle Ziele nach oben."}
MultiLanguageSpellData['de'][257618] = {name = "Ausweiden", additional_info = "{20 Energie} {/ 5 Combopunkte Nahkampfreichweite}\nSofort\nBenötigt Nahkampfwaffe\n[q]Finishing-Move, der das Ziel ausweidet und gewaltigen Schaden verursacht."}
MultiLanguageSpellData['de'][257619] = {name = "Geschenk der Lebensbinderin", additional_info = "Unbegrenzte Reichweite\nWirken in 8 sek.\n[q]Eonar erschafft das Geschenk der Lebensbinderin, einen lebensspendenden Baum, der hervorsprießt, um die Spielercharaktere zu retten. Das Geschenk der Lebensbinderin wird abhängig von der Schlachtzugsgröße mit mehreren Aufladungen von 'Lebensspendende Wurzeln' erschaffen. Spielercharaktere können das Geschenk der Lebensbinderin heilen.\n\n Während das Geschenk der Lebensbinderin lebt, können Spielercharaktere während des Kampfes gegen Argus nach ihrem Tod beliebig ihren Geist freilassen, um als Geist zum Ort der Begegnung zurückzukehren. Wenn sich ein Spielercharakter als Geist dem Baum nähert, wird er wiederbelebt und eine Aufladung von 'Lebensspendende Wurzeln' wird entfernt. Sobald die Aufladungen von 'Lebensspendende Wurzeln' verbraucht sind, ruft eine Wiederbelebung durch das Geschenk der Lebensbinderin bei ihr einen Stapel 'Verdorrte Wurzeln' hervor."}
MultiLanguageSpellData['de'][257620] = {name = "Mehrfachschuss", additional_info = "{30 Fokus} {40 Meter Reichweite}\nSofort\nBenötigt Distanzwaffe\n[q]Feuert eine Geschosssalve ab, die Euer aktuelles Ziel sowie alle Gegner innerhalb von 10 Metern trifft und ihnen (50.76% der Angriffskraft) körperlichen Schaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. [ Tödliche Schüsse : 'Mehrfachschuss' hat eine Chance von 30%, die Abklingzeit von 'Schnellfeuer' um 5.0 Sek. zu verringern ]"}
MultiLanguageSpellData['de'][257621] = {name = "Gekonnte Schüsse", additional_info = "[q]Wenn 'Mehrfachschuss' 3 oder mehr Ziele trifft, prallt Euer nächster Einsatz von 'Gezielter Schuss' oder 'Schnellfeuer' auf bis zu 5 zusätzliche Ziele ab und fügt ihnen 60% des normalen Schadens zu."}
