MultiLanguageSpellData['de'][257628] = {name = "Versteinernder Blick", additional_info = "20 Meter Reichweite\nKanalisiert (Wirken in 4 sek.)\n[q]Der Zaubernde fokussiert einen versteinernden Blick auf alle Spielercharaktere vor ihm. Wenn er den Blick erfolgreich abschließt, wird das Opfer für 4 Sek. in Stein verwandelt."}
