MultiLanguageSpellData['de'][257671] = {name = "Golganneths donnernde Wut", additional_info = "100 Meter Reichweite\nSofort\n[q]Eure Schaden verursachenden Fähigkeiten haben eine Chance, an der Position Eures Ziels einen wütenden Sturm zu erschaffen, der innerhalb von 6 Metern im Verlauf von 6 Sek. ( 172 * 6) Naturschaden verursacht, der auf alle betroffenen Gegner aufgeteilt wird.\n\nGolganneths donnernde Wut\n Wenn Euch das Pantheon Macht verleiht, rufen Eure automatischen Angriffe eine Blitzexplosion hervor, die allen Gegnern innerhalb von 8 Metern um das Ziel [ 1 * (Haupthandwaffen-Min-Grundgeschwindigkeit) * 96 ] Naturschaden zufügt. Hält 15 Sek. lang an."}
MultiLanguageSpellData['de'][257673] = {name = "Lebensenergie", additional_info = "Sofort\n[q]Eonars Lebensenergie steigt mit jedem bezwungenen Legionsinvasor. Beim Erreichen von 100 Lebensenergie greift sie die Paraxis sowie alle Streitkräfte der Legion mit 'Lebenskraft' an.\n\n\nLebenskraft Unbegrenzte Reichweite Wirken in 3 Sek. Eonar sammelt ihre Lebenskraft an und überzieht die Paraxis mit Naturschaden. Zusätzlich fegt eine Schockwelle über die Zone hinweg, die allen gegnerischen Eindringlingen Schaden zufügt."}
MultiLanguageSpellData['de'][257674] = {name = "Verstohlenheit", additional_info = "{Sofort} {2 sek. Abklingzeit}\n[q]Verbirgt Euch bis zum Abbruch in den Schatten, wodurch Ihr um Gegner herumschleichen könnt, ohne gesehen zu werden.\n\n Während Ihr verborgen seid, regeneriert Ihr alle 1 Sek. 2 Gesundheit."}
MultiLanguageSpellData['de'][257676] = {name = "Rekonstruieren", additional_info = "Wirken in 2.5 sek.\n[q]Der Zaubernde zieht Steine und Trümmer an, um Sprünge in seiner Gestalt auszufüllen, was ihn 10 Sek. lang alle 1 Sek. um 4% seiner maximalen Gesundheit heilt."}
MultiLanguageSpellData['de'][257677] = {name = "Rekonstruieren", additional_info = "Wirken in 2.5 sek.\n[q]Ordnet ein Bombardement an der Position des Zaubernden an, das an jedem Einschlagsort Feuerschaden verursacht."}
