MultiLanguageSpellData['de'][257702] = {name = "Schattenklingen", additional_info = "100 Meter Reichweite\nSofort\n[q]Eure Schaden verursachenden Zauber haben eine Chance, 6 Schattenklingen zu beschwören. Nach 2 Sek. beginnen die Klingen, vorwärts zu fliegen. Jede fügt dem ersten getroffenen Gegner in ihrem Weg 366 Schattenschaden zu und erhöht den durch weitere Schattenklingen erlittenen Schaden 3 Sek. lang um 10%, bis zu maximal 50%."}
