MultiLanguageSpellData['de'][257709] = {name = "8.0 Blacksmithing", additional_info = "Sofort\n[q]Ermöglicht einem Koch, raffinierte Wokgerichte mit einer maximalen Fertigkeit von 600 zu kochen."}
MultiLanguageSpellData['de'][257710] = {name = "8.0 Blacksmithing - Teach", additional_info = nil}
MultiLanguageSpellData['de'][257715] = {name = "Zeremonielle Knochensäge", additional_info = "Wirken in 2 sek.\n[q]Die Drust setzten in ihren Ritualen oft allerhand Tiere ein und nutzten hauptsächlich ihre Organe. Knochensägen waren dabei wichtig, vor allem um in den Brustkorb größerer Tiere einzudringen, um an das Herz zu gelangen."}
MultiLanguageSpellData['de'][257716] = {name = "Uralter runengebundener Foliant", additional_info = "Wirken in 2 sek.\n[q]Folianten wurden oft von den Stärksten der Drust geführt, die darin ihre Zauberformeln niederschrieben und sie zum Fokussieren ihrer Macht nutzten. Gelehrte haben in der Vergangenheit versucht, die uralten Texte in diesen Folianten zu übersetzen. Im Zuge dessen verfielen sie jedoch mit wachsendem Verständnis der Schriften immer mehr dem Wahnsinn."}
MultiLanguageSpellData['de'][257717] = {name = "Ausweidungssichel", additional_info = "Wirken in 2 sek.\n[q]Es wurden bereits viele Werkzeuge entdeckt, welche die Drust in ihren Ritualen benutzten. Dazu gehört auch eine Sichel, mit der sie die Bäuche ihrer Opferungen aufrissen, um die Eingeweide freizulegen und an die benötigten Organe für ihre dunklen Rituale zu gelangen."}
MultiLanguageSpellData['de'][257718] = {name = "Gezackte Klinge der Drust", additional_info = "Wirken in 2 sek.\n[q]Die Klingen der Drust sind furchteinflößend und wurden sowohl für den Kampf als auch für uralte Zeremonien benutzt. In den Händen eines Drust konnte eine solche Klinge in Sekundenschnelle ihren Weg in jedes beliebige lebenswichtige Organ finden."}
MultiLanguageSpellData['de'][257719] = {name = "Ritualfetisch", additional_info = "Wirken in 2 sek.\n[q]Als die Drust erstmals erlernten, Seelen in Konstrukte einzubetten, nutzten sie die Gebeine ihrer Toten als Wirt. Nach den abgeschlossenen Ritualen sollen diese Fetische ein unheimliches, blaues Licht ausgestrahlt haben. Dabei handelte es sich wahrscheinlich um eine Manifestierung der Essenz der Seelenmacht."}
MultiLanguageSpellData['de'][257720] = {name = "Vase von Akun'Jar", additional_info = "Wirken in 2 sek.\n[q]Die Zandalari verehren viele mächtige Geistergötter, bekannt als die Loa. Einer von ihnen ist die große Donnerechse Akunda, der Loa der Stürme und Neuanfänge. Er glaubt daran, dass der Sturm die Macht hat, Bedauern und Kummer hinwegzuspülen."}
MultiLanguageSpellData['de'][257721] = {name = "Urne des Übergangs", additional_info = "Wirken in 2 sek.\n[q]Während der letzten Ära des Rats der Stämme brach eine Blutseuche aus, der tausende Trolle zum Opfer fielen. Es wurde entschieden, dass einige Körper zu stark verseucht waren, um sie angemessen zu beerdigen. Stattdessen wurden sie verbrannt und in speziellen Urnen aufbewahrt. Mit der Zeit wurde diese Methode bei den Zandalari zum Standard, wenn es um die Bestattung ihrer Toten ging."}
MultiLanguageSpellData['de'][257722] = {name = "Götze von Rezan", additional_info = "Wirken in 2 sek.\n[q]Im Laufe der Zeitalter haben viele Könige das Zandalariimperium regiert. Jeder von ihnen wusste jedoch, den großen Loa Respekt zu erweisen, und sie alle brachten ihre Ehrerbietung dem mächtigsten von ihnen dar, nämlich Rezan. Dieser Loa schätzt Taten mehr als Worte, doch er lässt auch kleine Nachlässigkeiten nicht außer Acht und ist bekannt für seinen langgehegten Groll."}
MultiLanguageSpellData['de'][257723] = {name = "Hochapothekerkapuze", additional_info = "Wirken in 2 sek.\n[q]Die Alchemisten unter den Zandalari verbanden sich innerhalb des Imperiums zu einer verschworenen Gemeinschaft namens \"Shadra'Zan\". Der Eintritt in die Gilde beinhaltete ein Ritual, das vom Initianden erforderte, einen aus seinem eigenen Blut gemischten Trank zu trinken. Sollte er den Effekten widerstehen, wurde er als würdig erachtet, die streng gehüteten Geheimnisse zu erlernen."}
MultiLanguageSpellData['de'][257724] = {name = "Voodoomaske von Bwonsamdi", additional_info = "Wirken in 2 sek.\n[q]Um den Loa des Todes zu ehren, trugen die Zandalari diese Masken während des Rituals seiner Anbetung. Seinerseits würde Bwonsamdi entweder in aller Güte antworten oder sie mit Schmerz verfluchen, je nach seiner Laune. Bwonsamdi ist der Beschützer der Toten und bringt die Geister seiner Anhänger in sein Reich, die \"Andre Seite\"."}
MultiLanguageSpellData['de'][257730] = {name = "Segen des Himmelsrufers", additional_info = "Wirken in 30 sek.\n[q]Erfüllt Sethrak in der Nähe mit der Macht des Sturms."}
MultiLanguageSpellData['de'][257731] = {name = "Den Schleier durchbrech'n", additional_info = nil}
MultiLanguageSpellData['de'][257732] = {name = "Erschütterndes Brüllen", additional_info = "Nahkampfreichweite\n{Wirken in} {2.75 sek. 3 sek. Abklingzeit}\n[q]Lässt ein mächtiges Heulen los, das 3927608 körperlichen Schaden verursacht und für 1.5 Sek. das Zauberwirken unterbricht."}
MultiLanguageSpellData['de'][257734] = {name = "Raouls \"Notvorrat\"", additional_info = "100 Meter Reichweite\n{Wirken in} {1 sek. 5 sek. Abklingzeit}\n[q]Raouls \"Notvorrat\" ist ein heftiges Gebräu, das 12 Naturschaden verursacht. Sobald das Ziel 10 Stapel von Raouls \"Notvorrat\" angesammelt hat, wird es für 10 Sek. in Schlaf versetzt. Bewegung beendet diesen Effekt."}
MultiLanguageSpellData['de'][257735] = {name = "Unter den Tisch", additional_info = "Sofort\n[q]Raoul kann Euch unter den Tisch trinken! Fällt für 10 Sek. in tiefen Schlaf."}
