MultiLanguageSpellData['de'][259409] = {name = "Kombüsenbankett", additional_info = "5 Meter Reichweite\nWirken in 1 sek.\n[q]Richtet ein Kombüsenbankett her, das bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\n Stellt im Verlauf von 20 Sek. 19231 Gesundheit und 11538 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und ein Wert wird 1 Stunde lang um 35 erhöht."}
