MultiLanguageSpellData['de'][260172] = {name = "Apfelschimmel", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euren Apfelschimmel der Sturmwacht oder gibt ihn wieder frei.\n[q]\"Ein beliebtes Reittier bei den Meerespriestern, die in Sturmsang beheimatet sind.\"\nVerkäufer:\nSchwester Liliana\nZone:\nDas Sturmsangtal\nDie Sturmwacht - Ehrfürchtig\nKosten:\n10.000"}
MultiLanguageSpellData['de'][260173] = {name = "Nebelgraues Streitross", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euer rußschwarzes Kronsteigstreitross oder gibt es wieder frei.\n[q]\"Diese Rösser gehören zu den ältesten Pferderassen in Kul Tiras und sind sogar viele Male im ersten Kampf gegen die Drust vorangestürmt.\"\nVerkäufer:\nRüstmeister Alkorn\nZone:\nDrustvar\nDer Glutorden - Ehrfürchtig\nKosten:\n10.000"}
MultiLanguageSpellData['de'][260174] = {name = "Verängstigtes Packmuli", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Euer verängstigtes Packmuli oder gibt es wieder frei.\n[q]\"Dieses arme Muli befand sich in Drustvar, als die Hexen dort die Herrschaft an sich rissen. Es hat schon zu viel miterlebt.\"\nZone:\nDrustvar"}
MultiLanguageSpellData['de'][260175] = {name = "Goldmähne", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört Goldmähne oder gibt ihn wieder frei.\n[q]\"Lord Sturmsang befahl seinen Handlangern, dieses Pferd vom Anwesen der Norwinsens in Tiragarde zu stehlen, da er seine herrliche goldene Mähne begehrte.\"\nZone:\nSturmsangtal"}
