MultiLanguageSpellData['de'][272109] = {name = "Auslöschungsstrahl", additional_info = "Sofort\n[q]Beschwört eine Vergessenssphäre in der Nähe eines Gegners. Die Vergessenssphäre betört alle Spielercharaktere innerhalb von 5 Metern.\n\n Während der Betörung erhalten die Betroffenen alle 2 Sek. jeweils Stapel von 'Vernichtung'.\n\n Spielercharaktere bleiben unter der Kontrolle der Sphäre, bis sie aus dem Wirkungsbereich gestoßen werden. Angriffe auf Spielercharaktere unter dem Einfluss der Vergessenssphäre stoßen diese ein Stück zurück.\n\n Wenn ein Spielercharakter vom Einfluss befreit wird, löst er 'Hereinbrechendes Vergessen' aus."}
MultiLanguageSpellData['de'][272110] = {name = "Auslöschungsstrahl", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Beschwört eine Vergessenssphäre in der Nähe eines Gegners. Die Vergessenssphäre betört alle Spielercharaktere innerhalb von 5 Metern.\n\n Während der Betörung erhalten die Betroffenen alle 2 Sek. jeweils Stapel von 'Vernichtung'.\n\n Spielercharaktere bleiben unter der Kontrolle der Sphäre, bis sie aus dem Wirkungsbereich gestoßen werden. Angriffe auf Spielercharaktere unter dem Einfluss der Vergessenssphäre stoßen diese ein Stück zurück.\n\n Wenn ein Spielercharakter vom Einfluss befreit wird, löst er 'Hereinbrechendes Vergessen' aus."}
