MultiLanguageSpellData['de'][272119] = {name = "Gunst von Pa'ku", additional_info = "Sofort\n[q]Das Töten eines Ziels löst Winde von Pa'ku aus.\n\n Dieser Effekt kann nur einmal alle 60 Sek. auftreten.\n\n Winde von Pa'ku\n Erhöht 15 Sek. lang das Tempo um 5% und die Bewegungsgeschwindigkeit um 25%.\n(1Min. Abklingzeit)"}
