MultiLanguageSpellData['de'][272121] = {name = "Gunst von Akunda", additional_info = "Sofort\n[q]Angriffe und Heilungen haben eine Chance, Lichtsturm auszulösen.\n\n Dieser Effekt kann nur einmal alle 60 Sek. auftreten.\n\n Lichtsturm\n Verbreitet Lichtsturmenergie auf das Ziel, die auf Ziele in der Nähe überspringt und dabei Verbündete heilt oder Gegnern Schaden zufügt.\n(1Min. Abklingzeit)"}
MultiLanguageSpellData['de'][272122] = {name = "Gunst von Bwonsamdi", additional_info = "Sofort\n[q]Beim Töten eines Gegners besteht eine Chance, dass Pakt mit Bwonsamdi ausgelöst wird.\n\n Pakt mit Bwonsamdi\n Ein Fluch, der nach 4 Sek. explodiert und allen Gegnern in der Nähe Schaden zufügt sowie einen Diener von Bwonsamdi beschwört.\n(Procchance: 50%, 3s Abklingzeit)"}
