MultiLanguageSpellData['de'][273323] = {name = "Blitzschlagschildüberladung", additional_info = "60 Meter Reichweite\nSofort\n[q]Elementar\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\n Es besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden, und eine Chance von 100%, dass sie 5 Mahlstrom erzeugen.\n\n Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n\nVerstärkung\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\n Es besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden, und eine Chance von 50%, dass sie einen Stapel von 'Waffe des Mahlstroms' erzeugen.\n\n Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n\nWiederherstellung\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\n Es besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden.\n\n Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein."}
MultiLanguageSpellData['de'][273324] = {name = "Blitzschlagschild", additional_info = "100 Meter Reichweite\nSofort\n[q]Elementar\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\n Es besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden, und eine Chance von 100%, dass sie 5 Mahlstrom erzeugen.\n\n Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n\nVerstärkung\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\n Es besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden, und eine Chance von 50%, dass sie einen Stapel von 'Waffe des Mahlstroms' erzeugen.\n\n Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein.\n\nWiederherstellung\nUmgibt Euch 1 Stunde lang mit einem Blitzschild.\n\n Es besteht eine Chance von 100%, dass Nahkampfangreifer (21.75% der Zaubermacht) Naturschaden erleiden.\n\n Es kann immer nur ein Elementarschild auf dem Schamanen aktiv sein."}
