MultiLanguageSpellData['de'][273844] = {name = "Blitzschlag", additional_info = "40 Meter Reichweite\nWirken in 2 sek.\n[q]Überzieht einen Gegner mit Blitzen und fügt ihm Naturschaden zu."}
MultiLanguageSpellData['de'][273845] = {name = "Kettenblitzschlag", additional_info = "30 Meter Reichweite\n{Wirken in} {2 sek. 6 sek. Abklingzeit}\n[q]Trifft einen Gegner mit einem Blitzschlag, der auf einen weiteren Gegner in der Nähe überspringt. Der Zauber wirkt auf bis zu 3 Ziele und fügt jedem folgenden Ziel immer geringeren Naturschaden zu."}
MultiLanguageSpellData['de'][273846] = {name = "Totem des heilenden Flusses", additional_info = "40 Mana\nSofort\n[q]Beschwört ein Totem des heilenden Flusses mit 5 Gesundheit zu Füßen des Zaubernden, das Verbündete in der Nähe alle 2 Sek. um 0 Gesundheit heilt. Hält 1 Min. lang an."}
MultiLanguageSpellData['de'][273847] = {name = "Heilender Fluss", additional_info = "Sofort\n[q]Beschwört für 15 Sek. ein Totem zu Euren Füßen, das [ Rauschende Ströme : zwei verletzte Gruppen- oder Schlachtzugsmitglieder / ein verletztes Gruppen- oder Schlachtzugsmitglied] innerhalb von 40 Metern alle 2 Sek. um (67.68% der Zaubermacht) Gesundheit heilt.\n\n Wenn Ihr [ Totem des Wolkenbruchs : ' Totem des Wolkenbruchs ' / ' Totem des heilenden Flusses '] bereits erlernt habt, erhaltet Ihr stattdessen 1 zusätzliche Aufladung von [ Totem des Wolkenbruchs : ' Totem des Wolkenbruchs ' / ' Totem des heilenden Flusses ']."}
MultiLanguageSpellData['de'][273848] = {name = "Totem des heilenden Flusses", additional_info = "100 Meter Reichweite\nSofort\n[q]Heilt ein verletztes Gruppen- oder Schlachtzugsmitglied in der Nähe."}
