MultiLanguageSpellData['de'][279183] = {name = "Diskreter Zauberfaden", additional_info = "Wirken in 2 sek.\nBenötigt Umhang\nReagenzien:\nGischtvernebeltes Leinen (20), Tiefseesatin (8), Nylonfaden (10)\n[q]Bestickt Euren Umhang dauerhaft mit einem diskreten Zauberfaden, der Eure mit Angriffen und Zaubern erzeugte Bedrohung verringert. Nur der Umhang des Schneiders kann bestickt werden und wird dadurch seelengebunden.\nBerufsausbilder:\nSchneiderei von Battle for Azeroth (75)\nKosten:\n3\n50"}
MultiLanguageSpellData['de'][279184] = {name = "Federleichter Zauberfaden", additional_info = "Wirken in 2 sek.\nBenötigt Umhang\nReagenzien:\nGischtvernebeltes Leinen (20), Tiefseesatin (8), Nylonfaden (10)\n[q]Bestickt Euren Umhang dauerhaft mit einem federleichten Zauberfaden, der es Euch gestattet, tiefer zu fallen, bevor Ihr Fallschaden erleidet. Nur der Umhang des Schneiders kann bestickt werden und wird dadurch seelengebunden.\nBerufsausbilder:\nSchneiderei von Battle for Azeroth (75)\nKosten:\n3\n50"}
