MultiLanguageSpellData['de'][280709] = {name = "Archiv der Titanen", additional_info = "Sofort\n[q]Eure Rüstung sammelt und analysiert alle 5 Sek. Kampfdaten, wodurch Euer Primärwert um 2 erhöht wird. Bis zu 20-mal stapelbar. Außerhalb des Kampfes verfallen die Daten langsam.\n\n Schaltet ' Neuerschaffungsfeld ' in Uldir frei."}
MultiLanguageSpellData['de'][280710] = {name = "Champion von Azeroth", additional_info = "[q0]Azeritmacht\n[q]Eure Zauber und Fähigkeiten haben eine Chance, alle Sekundärwerte 1 Min. lang um 4 zu erhöhen. Bis zu 4-mal stapelbar."}
MultiLanguageSpellData['de'][280712] = {name = "Champion von Azeroth", additional_info = "[q0]Azeritmacht\nSofort\nCa. 4 Procs pro Minute\n[q]Eure Zauber und Fähigkeiten haben eine Chance, alle Sekundärwerte 1 Min. lang um 4 zu erhöhen. Bis zu 4-mal stapelbar.\n(15s Abklingzeit)"}
MultiLanguageSpellData['de'][280713] = {name = "Champion von Azeroth", additional_info = "[q0]Azeritmacht\nSofort\n[q]Eure Zauber und Fähigkeiten haben eine Chance, alle Sekundärwerte 1 Min. lang um 4 zu erhöhen. Bis zu 4-mal stapelbar."}
MultiLanguageSpellData['de'][280715] = {name = "Wirbelwind", additional_info = "Sofort\nBenötigt Nahkampfwaffe\n[q]Entfesselt einen Wirbel aus Stahl, der allen Gegnern in der Nähe [(41.9991% der Angriffskraft) + (41.9991% der Angriffskraft) + (2 * ((41.9991% der Angriffskraft) + (41.9991% der Angriffskraft)))] körperlichen Schaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. [ Verbesserter Wirbelwind : Lässt 2 Nahkampfangriffe gegen Einzelziele bis zu 4 zusätzliche Ziele treffen und ihnen 4% des Schadens zufügen ] [ Erzeugt 3 Wut sowie 1 Wut pro getroffenem Ziel. ]"}
MultiLanguageSpellData['de'][280716] = {name = "Egelgift", additional_info = "[q]Fügt Euren tödlichen Giften den Effekt von Egelgift hinzu, der Euch 3% Lebensraub gewährt."}
MultiLanguageSpellData['de'][280717] = {name = "Verborgene Shuriken", additional_info = "[q]Erhöht alle 2 Sek. den Schaden Eures nächsten Einsatzes von 'Shurikensturm' um 20%. Bis zu 20-mal stapelbar."}
MultiLanguageSpellData['de'][280718] = {name = "Verborgene Klingen", additional_info = "Sofort\n[q]Erhöht alle 2 Sek. den Schaden Eures nächsten Einsatzes von 'Shurikensturm' um 20%. Bis zu 20-mal stapelbar."}
MultiLanguageSpellData['de'][280719] = {name = "Geheimtechnik", additional_info = "{30 Energie} {/ 1 zu 5 Combopunkte Nahkampfreichweite}\nSofort 1 min Abklingzeit\n[q]Finishing-Move, der Schattenklone von Euch erschafft. Ihr und Eure Schattenklone führen jeweils einen Angriff aus, der alle Gegner in der Nähe Eures Primärziels durchbohrt und diesem körperlichen Schaden sowie anderen Zielen verringerten Schaden zufügt.\n 1 Punkt: insgesamt [(19% der Angriffskraft) * 3] Schaden\n 2 Punkte: insgesamt [(19% der Angriffskraft) * 2 * 3] Schaden\n 3 Punkte: insgesamt [(19% der Angriffskraft) * 3 * 3] Schaden\n 4 Punkte: insgesamt [(19% der Angriffskraft) * 4 * 3] Schaden\n 5 Punkte: insgesamt [(19% der Angriffskraft) * 5 * 3] Schaden\n [  6 Punkte: insgesamt [(19% der Angriffskraft) * 6 * 3] Schaden] [  7 Punkte: insgesamt [(19% der Angriffskraft) * 7 * 3] Schaden]\n Verringert die Abklingzeit für jeden verbrauchten Combopunkt um 1 Sek."}
MultiLanguageSpellData['de'][280720] = {name = "Geheimtechnik", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Finishing-Move, der Schattenklone von Euch erschafft. Ihr und Eure Schattenklone führen jeweils einen Angriff aus, der alle Gegner in der Nähe Eures Primärziels durchbohrt und diesem körperlichen Schaden sowie anderen Zielen verringerten Schaden zufügt.\n 1 Punkt: insgesamt [(19% der Angriffskraft) * 3] Schaden\n 2 Punkte: insgesamt [(19% der Angriffskraft) * 2 * 3] Schaden\n 3 Punkte: insgesamt [(19% der Angriffskraft) * 3 * 3] Schaden\n 4 Punkte: insgesamt [(19% der Angriffskraft) * 4 * 3] Schaden\n 5 Punkte: insgesamt [(19% der Angriffskraft) * 5 * 3] Schaden\n [  6 Punkte: insgesamt [(19% der Angriffskraft) * 6 * 3] Schaden] [  7 Punkte: insgesamt [(19% der Angriffskraft) * 7 * 3] Schaden]\n Verringert die Abklingzeit für jeden verbrauchten Combopunkt um 1 Sek."}
MultiLanguageSpellData['de'][280721] = {name = "Plötzlicher Tod", additional_info = "Ca. 1.7 Procs pro Minute\n[q]Eure Angriffe haben eine Chance, die Abklingzeit von Hinrichten' abzuschließen und die Fähigkeit gegen jedes Ziel einsetzbar zu machen, unabhängig von seiner Gesundheit.\n(3s Abklingzeit)"}
